def p(text,bold=False):
    q=doc.add_paragraph();q.add_run(text).bold=bold;return q
def h(text):doc.add_heading(text,2)
def page(title):
    doc.add_page_break();doc.add_heading(title,1)
def table(headers,rows,widths):
    t=doc.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
    for c,w in zip(t.columns,widths):c.width=Cm(w)
    for c,x in zip(t.rows[0].cells,headers):c.text=x
    for row in rows:
        for c,x in zip(t.add_row().cells,row):c.text=x
    for i,row in enumerate(t.rows):
        pr=row._tr.get_or_add_trPr()
        no=OxmlElement('w:cantSplit');pr.append(no)
        if i==0:
            repeat=OxmlElement('w:tblHeader');pr.append(repeat)
        for c,w in zip(row.cells,widths):
            c.width=Cm(w);c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            tcPr=c._tc.get_or_add_tcPr()
            borders=OxmlElement('w:tcBorders')
            for edge in ['top','left','bottom','right']:
                b=OxmlElement('w:'+edge);b.set(qn('w:val'),'single');b.set(qn('w:sz'),'4');b.set(qn('w:color'),'D9D9D9');borders.append(b)
            tcPr.append(borders)
            margins=OxmlElement('w:tcMar')
            for side in ['top','left','bottom','right']:
                e=OxmlElement('w:'+side);e.set(qn('w:w'),'85');e.set(qn('w:type'),'dxa');margins.append(e)
            tcPr.append(margins)
            fill=OxmlElement('w:shd');fill.set(qn('w:fill'),'DCE6F1' if i==0 else ('F5F7FA' if i%2 else 'FFFFFF'));tcPr.append(fill)
            for par in c.paragraphs:
                par.paragraph_format.space_after=Pt(2);par.paragraph_format.line_spacing=1.03
                for r in par.runs:r.font.size=Pt(9.5);r.bold=(i==0)
    doc.add_paragraph().paragraph_format.space_after=Pt(1)
    return t

